// Custom implicit function for Diamond Nodal TPMS
class ImplicitTPMS : IImplicit
{
    private Library _lib;
    private ETPMS _type;
    private float _period;
    private Vector3 _phase;

    public ImplicitTPMS(Library lib, ETPMS type, float period, Vector3 phase)
    {
        _lib = lib;
        _type = type;
        _period = period;
        _phase = phase;
    }

    public float fSignedDistance(in Vector3 p)
    {
        Vector3 q = p / _period - _phase;
        float x = q.X;
        float y = q.Y;
        float z = q.Z;

        float f = 0;
        switch (_type)
        {
            case ETPMS.Diamond:
                f = 2 * (Mathf.Sin(2 * Mathf.PI * x) * Mathf.Cos(2 * Mathf.PI * y) * Mathf.Cos(2 * Mathf.PI * z) +
                       Mathf.Cos(2 * Mathf.PI * x) * Mathf.Sin(2 * Mathf.PI * y) * Mathf.Cos(2 * Mathf.PI * z) +
                       Mathf.Cos(2 * Mathf.PI * x) * Mathf.Cos(2 * Mathf.PI * y) * Mathf.Sin(2 * Mathf.PI * z)) -
                  1;
                break;
        }

        return f * _period;
    }

    public bool bGetValue(in Vector3 p, out float value)
    {
        value = fSignedDistance(p);
        return true;
    }

    public enum ETPMS
    {
        Diamond
    }
}
