            Vector3 q = p / period - phase;
            float x = q.X;
            float y = q.Y;
            float z = q.Z - zOffset;

            float f = MathF.Sin(x) * MathF.Cos(y) * MathF.Cos(z) +
                     MathF.Cos(x) * MathF.Sin(y) * MathF.Cos(z) +
                     MathF.Cos(x) * MathF.Cos(y) * MathF.Sin(z);

            value = f;
            return true;
        }

        public float fSignedDistance(in Vector3 p)
        {
            bGetValue(p, out float value);
            return value;
        }
    }
}
