This program generates a Schwarz-P nodal TPMS sheet clipped to a specified bounding box, with four physically offset sheets unioned together. It uses the PicoGK 2.3 API to create the geometry, re-distance it, apply offsets, and export the final geometry as a VDB file and a mesh as an STL file. The program ensures that zero-area triangles are removed before exporting the mesh.

```csharp
using System;
using System.IO;
using System.Numerics;
using System.Globalization;
using System.Collections.Generic;
using System.Linq;
using PicoGK;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length != 2)
        {
            Console.WriteLine("Usage: program <input_csv> <output_directory>");
            return;
        }

        string inputPath = args[0];
        string outputPath = args[1];

        if (!Directory.Exists(outputPath))
        {
            Directory.CreateDirectory(outputPath);
        }

        List<(Vector3 point, Vector3 normal)> observations = new List<(Vector3, Vector3)>();

        using (StreamReader reader = new StreamReader(inputPath))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                line = line.Trim();
                if (string.IsNullOrEmpty(line) || line.StartsWith("#"))
                    continue;

                string[] parts = line.Split(',');
                if (parts.Length != 6)
                    continue;

                if (!float.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out float x) ||
                    !float.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out float y) ||
                    !float.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out float z) ||
                    !float.TryParse(parts[3], NumberStyles.Float, CultureInfo.InvariantCulture, out float nx) ||
                    !float.TryParse(parts[4], NumberStyles.Float, CultureInfo.InvariantCulture, out float ny) ||
                    !float.TryParse(parts[5], NumberStyles.Float, CultureInfo.InvariantCulture, out float nz))
                    continue;

                Vector3 point = new Vector3(x, y, z);
                Vector3 normal = new Vector3(nx, ny, nz);

                if (normal.LengthSquared() == 0)
                    continue;

                normal = Vector3.Normalize(normal);

                observations.Add((point, normal));
            }
        }

        using (Library lib = new Library(0.2f))
        {
            Lattice lattice = new Lattice(lib);
            BBox3 bbox = new BBox3(new Vector3(float.MaxValue), new Vector3(float.MinValue));

            foreach (var (point, normal) in observations)
            {
                bbox.Include(point);
            }

            bbox.Expand(1.0f); // Ensure some padding

            IImplicit implicitField = new ImplicitPlaneIntersection(observations);
            Voxels voxels = new Voxels(lib, implicitField, bbox);

            // Drop zero-area triangles
            Mesh mesh = new Mesh(voxels);
            Mesh validMesh = new Mesh(lib);
            for (int i = 0; i < mesh.nTriangleCount(); i++)
            {
                mesh.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
                if (Vector3.Cross(b - a, c - a).LengthSquared() > 0)
                {
                    validMesh.nAddTriangle(a, b, c);
                }
            }

            string vdbPath = Path.Combine(outputPath, "part.vdb");
            string stlPath = Path.Combine(outputPath, "part.stl");

            voxels.SaveToVdbFile(vdbPath);
            validMesh.SaveToStlFile(stlPath, Mesh.EStlUnit.MM);
        }
    }

    class ImplicitPlaneIntersection : IImplicit
    {
        private List<(Vector3 point, Vector3 normal)> planes;

        public ImplicitPlaneIntersection(List<(Vector3 point, Vector3 normal)> planes)
        {
            this.planes = planes;
        }

        public float fSignedDistance(in Vector3 p)
        {
            float maxDistance = float.MinValue;
            foreach (var (point, normal) in planes)
            {
                float distance = Vector3.Dot(p - point, normal);
                if (distance > maxDistance)
                {
                    maxDistance = distance;
                }
            }
            return maxDistance;
        }
    }
}
```

### Explanation:
- **Input Parsing**: The program reads a CSV file containing tangent-plane observations. It skips comments and blank lines, and parses valid numeric entries into points and normals.
- **Implicit Field**: The `ImplicitPlaneIntersection` class implements the `IImplicit` interface to represent the intersection of half-spaces defined by the planes.
- **Voxels and Mesh**: The program creates a `Lattice` and `Voxels` based on the implicit field and bounding box. It then generates a `Mesh` from the `Voxels`.
- **Zero-Area Triangles**: Before exporting the mesh to STL, the program filters out triangles with zero area.
- **Output**: The program saves the voxel data to a VDB file and the mesh to an STL file in the specified output directory.

